-- HireFlow AI schema and synthetic seed data
CREATE TABLE departments (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	cost_center VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	UNIQUE (cost_center)
);
CREATE TABLE candidates (
	id VARCHAR(30) NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	email VARCHAR(180) NOT NULL, 
	city VARCHAR(100) NOT NULL, 
	years_experience FLOAT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);
CREATE TABLE skills (
	id INTEGER NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE job_requisitions (
	id VARCHAR(30) NOT NULL, 
	department_id INTEGER NOT NULL, 
	title VARCHAR(120) NOT NULL, 
	location VARCHAR(100) NOT NULL, 
	employment_type VARCHAR(30) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	min_salary FLOAT NOT NULL, 
	max_salary FLOAT NOT NULL, 
	approved_by VARCHAR(100) NOT NULL, 
	approved_at DATETIME NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE candidate_skills (
	id INTEGER NOT NULL, 
	candidate_id VARCHAR(30) NOT NULL, 
	skill_id INTEGER NOT NULL, 
	proficiency VARCHAR(20) NOT NULL, 
	years_used FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (candidate_id, skill_id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id), 
	FOREIGN KEY(skill_id) REFERENCES skills (id)
);
CREATE TABLE resume_artifacts (
	id VARCHAR(40) NOT NULL, 
	candidate_id VARCHAR(30) NOT NULL, 
	file_name VARCHAR(180) NOT NULL, 
	file_type VARCHAR(20) NOT NULL, 
	file_size_kb INTEGER NOT NULL, 
	parsed_at DATETIME, 
	source VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (candidate_id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id)
);
CREATE TABLE interviewers (
	id VARCHAR(30) NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	department_id INTEGER NOT NULL, 
	active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE requisition_skills (
	id INTEGER NOT NULL, 
	requisition_id VARCHAR(30) NOT NULL, 
	skill_id INTEGER NOT NULL, 
	importance FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (requisition_id, skill_id), 
	FOREIGN KEY(requisition_id) REFERENCES job_requisitions (id), 
	FOREIGN KEY(skill_id) REFERENCES skills (id)
);
CREATE TABLE screening_rules (
	id INTEGER NOT NULL, 
	requisition_id VARCHAR(30) NOT NULL, 
	min_experience FLOAT NOT NULL, 
	minimum_score FLOAT NOT NULL, 
	skill_weight FLOAT NOT NULL, 
	experience_weight FLOAT NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(requisition_id) REFERENCES job_requisitions (id)
);
CREATE TABLE applications (
	id VARCHAR(120) NOT NULL, 
	requisition_id VARCHAR(30) NOT NULL, 
	candidate_id VARCHAR(30) NOT NULL, 
	applied_at DATETIME NOT NULL, 
	stage VARCHAR(30) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	screening_score FLOAT NOT NULL, 
	duplicate_flag BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(requisition_id) REFERENCES job_requisitions (id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id)
);
CREATE TABLE interviews (
	id VARCHAR(30) NOT NULL, 
	application_id VARCHAR(120) NOT NULL, 
	interviewer_id VARCHAR(30) NOT NULL, 
	round_number INTEGER NOT NULL, 
	scheduled_start DATETIME NOT NULL, 
	scheduled_end DATETIME NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	conflict_flag BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(application_id) REFERENCES applications (id), 
	FOREIGN KEY(interviewer_id) REFERENCES interviewers (id)
);
CREATE TABLE offers (
	id VARCHAR(30) NOT NULL, 
	application_id VARCHAR(120) NOT NULL, 
	salary FLOAT NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	approved_by VARCHAR(100) NOT NULL, 
	approved_at DATETIME NOT NULL, 
	issued_at DATETIME NOT NULL, 
	response_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(application_id) REFERENCES applications (id)
);
CREATE TABLE application_events (
	id INTEGER NOT NULL, 
	application_id VARCHAR(120) NOT NULL, 
	from_stage VARCHAR(30), 
	to_stage VARCHAR(30) NOT NULL, 
	event_type VARCHAR(40) NOT NULL, 
	event_at DATETIME NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	note TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(application_id) REFERENCES applications (id)
);
CREATE TABLE feedback (
	id VARCHAR(100) NOT NULL, 
	interview_id VARCHAR(30) NOT NULL, 
	interviewer_id VARCHAR(30) NOT NULL, 
	technical_score FLOAT NOT NULL, 
	communication_score FLOAT NOT NULL, 
	problem_solving_score FLOAT NOT NULL, 
	recommendation VARCHAR(20) NOT NULL, 
	comments TEXT NOT NULL, 
	submitted_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(interview_id) REFERENCES interviews (id), 
	FOREIGN KEY(interviewer_id) REFERENCES interviewers (id)
);
